// Mood-Check: Lese energyLevel aus gestrigem context
// Falls < 5 → reduziertes Pensum, deep-rest-slot erzwingen
const missions = $('Supabase: Jarvis Missions laden').all();
const yesterdayCtx = missions[0]?.json?.[0]?.context || {};
const energyLevel  = parseInt(yesterdayCtx.energyLevel || 7);
const moodCheck    = energyLevel >= 5;
const deepRest     = energyLevel < 3;
const maxTasks     = deepRest ? 2 : energyLevel < 5 ? 3 : 5;

const leads = $('Supabase: Letzte Leads laden').all();
const leadSummary = leads[0]?.json?.map?.(l => l.company + ' (' + l.status + ')').join(', ') || 'Keine Daten';
const lastFocus   = missions[0]?.json?.[0]?.daily_focus || 'Kein Vortags-Fokus';

return [{ json: {
  energyLevel,
  moodCheck,
  deepRest,
  maxTasks,
  leadSummary,
  lastFocus,
  deepRestNote: deepRest ? '⚠️ DEEP-REST-SLOT: 30 Min. Pause VOR erstem Outreach. Nur 2 Kern-Tasks heute.' : ''
}}];

