// Extrahiere TOP_NISCHE aus Claude-Antwort für proaktiven Gemini-Trigger
const text = $input.first().json.content[0].text;
let topNische = 'Digitale Automatisierung';
let topPillar = 'Bot-Empire';
try {
  const match = text.match(/\{[^{}]*\"top_nische\"[^{}]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    topNische = parsed.top_nische || topNische;
    topPillar = parsed.top_pillar || topPillar;
  }
} catch(e) {}
return [{ json: { text, topNische, topPillar } }];

