  posts = JSON.parse(match ? match[0] : raw).posts || [];
} catch(e) { posts = []; }
const formatted = posts.map((p, i) =>
  `*Post ${i+1}:*\n🎯 ${p.hook}\n${p.body}\n\n📢 ${p.cta}`
).join('\n\n━━━━━━━━━━━━━━━\n');
return [{ json: { formatted, count: posts.length } }];

