const raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '{"ideas":[]}';
let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  parsed = { ideas: [{ title: 'Parse-Fehler', hook: e.message, format: 'Error', cta: '', kpi_impact: 'niedrig' }] };
}
// 9.9M Filter: sortiere nach kpi_impact
const order = { 'hoch': 0, 'mittel': 1, 'niedrig': 2 };
parsed.ideas.sort((a, b) => (order[a.kpi_impact] || 2) - (order[b.kpi_impact] || 2));
return [{ json: parsed }];
